CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.is_admin()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_uid text := coalesce(auth.jwt()->>'sub', auth.uid()::text);
  v_role text;
  v_email text := auth.jwt()->>'email';
begin
  if v_uid is null then
    return false;
  end if;

  if (auth.jwt()->'app_metadata'->>'role') = 'admin' or (auth.jwt()->'user_metadata'->>'role') = 'admin' then
    return true;
  end if;

  -- Hardcoded admin email fallback
  if v_email in ('former-admin@example.invalid') then
    return true;
  end if;

  select role into v_role from public.users where id = v_uid;
  return coalesce(v_role = 'admin', false);
end;
$function$

CREATE OR REPLACE FUNCTION public.check_user_balance_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  -- bug #8 fix: security-definer RPCs (deposits, withdrawals, investments,
  -- portfolio buys/sells, copy trades, airdrop payouts, admin adjustments)
  -- set this flag while performing legitimate balance movements. When set,
  -- skip the guard for this statement only.
  if current_setting('app.bypass_balance_protection', true) = 'true' then
    return new;
  end if;

  if new.balance < 0 then
    raise exception 'User balance cannot be negative';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_user_balance(p_user_id text, p_new_balance numeric, p_reason text DEFAULT 'Manual balance adjustment by admin'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_old_balance numeric;
  v_diff numeric;
begin
  if not is_admin() then raise exception 'Only admins can perform manual balance adjustments'; end if;
  select balance into v_old_balance from public.users where id = p_user_id for update;
  if not found then raise exception 'User % not found', p_user_id; end if;
  
  v_diff := p_new_balance - v_old_balance;
  update public.users set balance = p_new_balance, updated_at = now() where id = p_user_id;

  insert into public.transactions (id, user_id, type, amount, currency, asset, status, notes)
  values (
    'tx-adj-' || extract(epoch from now())::bigint || '-' || floor(random()*1000)::text,
    p_user_id,
    'adjustment',
    abs(v_diff),
    'USD',
    'USD',
    'completed',
    p_reason || ' (Old: $' || v_old_balance || ', New: $' || p_new_balance || ')'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_investment(p_id text, p_user_id text, p_plan_id text, p_plan_name text, p_amount numeric, p_duration_days integer, p_roi_percent numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_balance numeric;
  v_profit numeric := (p_amount * p_roi_percent) / 100;
  v_caller text := auth.uid()::text;
begin
  if v_caller is null or (v_caller <> p_user_id and not is_admin()) then
    raise exception 'Unauthorized';
  end if;

  select balance into v_balance from public.users where id = p_user_id for update;
  if v_balance is null or v_balance < p_amount then
    raise exception 'Insufficient balance';
  end if;

  update public.users set balance = balance - p_amount where id = p_user_id;

  insert into public.active_investments (
    id, user_id, plan_id, plan_name, amount, start_date, end_date,
    roi_percent, expected_profit, total_return, accumulated_profit, status
  ) values (
    p_id, p_user_id, p_plan_id, p_plan_name, p_amount, now(), now() + (p_duration_days || ' days')::interval,
    p_roi_percent, v_profit, p_amount + v_profit, 0, 'Running'
  );

  insert into public.transactions (id, user_id, type, amount, currency, asset, status, notes)
  values (
    'tx-inv-' || extract(epoch from now())::bigint,
    p_user_id,
    'investment',
    p_amount,
    'USD',
    'USD',
    'completed',
    'Subscribed to ' || p_plan_name
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_copy_trade(p_id text, p_user_id text, p_trader_id text, p_trader_name text, p_amount numeric, p_duration_days integer DEFAULT 30, p_roi_percent numeric DEFAULT 45)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_balance numeric;
  v_profit numeric := (p_amount * p_roi_percent) / 100;
  v_caller text := auth.uid()::text;
begin
  if v_caller is null or (v_caller <> p_user_id and not is_admin()) then raise exception 'Unauthorized'; end if;
  select balance into v_balance from public.users where id = p_user_id for update;
  if v_balance is null or v_balance < p_amount then raise exception 'Insufficient balance'; end if;

  update public.users set balance = balance - p_amount where id = p_user_id;

  insert into public.copy_trades (
    id, user_id, trader_id, trader_name, amount_invested, roi_percent,
    expected_profit, total_return, start_timestamp, end_timestamp, status
  ) values (
    p_id, p_user_id, p_trader_id, p_trader_name, p_amount, p_roi_percent,
    v_profit, p_amount + v_profit, now(), now() + (p_duration_days || ' days')::interval, 'Running'
  );

  insert into public.transactions (id, user_id, type, amount, currency, asset, status, notes)
  values (
    'tx-cp-' || extract(epoch from now())::bigint,
    p_user_id,
    'investment',
    p_amount,
    'USD',
    'USD',
    'completed',
    'Started Copy Trading trader: ' || p_trader_name
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.buy_asset(p_user_id text, p_symbol text, p_name text, p_quantity numeric, p_price numeric, p_asset_type text DEFAULT 'crypto'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_total numeric := p_quantity * p_price;
  v_balance numeric;
  v_caller text := auth.uid()::text;
  v_pos record;
  v_new_amt numeric;
  v_new_avg numeric;
begin
  if v_caller is null or (v_caller <> p_user_id and not is_admin()) then raise exception 'Unauthorized'; end if;
  select balance into v_balance from public.users where id = p_user_id for update;
  if v_balance is null or v_balance < v_total then raise exception 'Insufficient balance'; end if;

  update public.users set balance = balance - v_total where id = p_user_id;

  select * into v_pos from public.portfolio_positions where user_id = p_user_id and symbol = p_symbol for update;
  if found then
    v_new_amt := v_pos.amount + p_quantity;
    v_new_avg := ((v_pos.amount * v_pos.avg_buy_price) + v_total) / v_new_amt;
    update public.portfolio_positions
    set amount = v_new_amt, avg_buy_price = v_new_avg, updated_at = now()
    where user_id = p_user_id and symbol = p_symbol;
  else
    insert into public.portfolio_positions (user_id, symbol, name, amount, avg_buy_price, asset_type)
    values (p_user_id, p_symbol, p_name, p_quantity, p_price, p_asset_type);
  end if;

  insert into public.transactions (id, user_id, type, amount, currency, asset, status, notes)
  values (
    'tx-buy-' || extract(epoch from now())::bigint,
    p_user_id,
    'investment',
    v_total,
    'USD',
    p_symbol,
    'completed',
    'Bought ' || p_quantity || ' ' || p_symbol || ' @ $' || p_price
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.sell_asset(p_user_id text, p_symbol text, p_quantity numeric, p_price numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_total numeric := p_quantity * p_price;
  v_caller text := auth.uid()::text;
  v_pos record;
begin
  if v_caller is null or (v_caller <> p_user_id and not is_admin()) then raise exception 'Unauthorized'; end if;
  select * into v_pos from public.portfolio_positions where user_id = p_user_id and symbol = p_symbol for update;
  if not found or v_pos.amount < p_quantity then raise exception 'Insufficient asset balance to sell'; end if;

  if v_pos.amount = p_quantity then
    delete from public.portfolio_positions where user_id = p_user_id and symbol = p_symbol;
  else
    update public.portfolio_positions set amount = amount - p_quantity, updated_at = now() where user_id = p_user_id and symbol = p_symbol;
  end if;

  update public.users set balance = balance + v_total where id = p_user_id;

  insert into public.transactions (id, user_id, type, amount, currency, asset, status, notes)
  values (
    'tx-sell-' || extract(epoch from now())::bigint,
    p_user_id,
    'payout',
    v_total,
    'USD',
    p_symbol,
    'completed',
    'Sold ' || p_quantity || ' ' || p_symbol || ' @ $' || p_price
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.approve_deposit_transaction(p_transaction_id text, p_notes text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare v_tx record;
begin
  if not is_admin() then raise exception 'Only an admin can approve deposits'; end if;
  select * into v_tx from transactions where id = p_transaction_id for update;
  if not found then raise exception 'Transaction % not found', p_transaction_id; end if;
  if v_tx.status <> 'pending' then return; end if;
  update transactions set status = 'completed', notes = coalesce(p_notes, notes) where id = p_transaction_id;
  perform set_config('app.bypass_balance_protection', 'true', true);
  update users set balance = balance + v_tx.amount where id = v_tx.user_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_copy_trade(p_id text, p_user_id text, p_trader_id text, p_trader_name text, p_amount_invested numeric, p_roi_percent numeric, p_expected_profit numeric, p_total_return numeric, p_start_timestamp timestamp with time zone, p_end_timestamp timestamp with time zone, p_remaining_days integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller text := auth.jwt()->>'sub';
  v_trader record;
  v_roi numeric;
  v_duration_days integer;
  v_expected_profit numeric;
  v_total_return numeric;
  v_start timestamptz := now();
  v_end timestamptz;
begin
  if v_caller is null or v_caller <> p_user_id then
    raise exception 'You can only copy-trade from your own account';
  end if;

  select * into v_trader from traders where id = p_trader_id;
  if not found then
    raise exception 'Trader not found: %', p_trader_id;
  end if;
  if v_trader.active = false then
    raise exception 'This trader is not accepting copy allocations';
  end if;

  if p_amount_invested is null or p_amount_invested <= 0 then
    raise exception 'Invalid copy amount';
  end if;
  if v_trader.min_copy_amount is not null and p_amount_invested < v_trader.min_copy_amount then
    raise exception 'Below minimum copy amount for this trader ($%)', v_trader.min_copy_amount;
  end if;
  if v_trader.max_copy_amount is not null and p_amount_invested > v_trader.max_copy_amount then
    raise exception 'Above maximum copy amount for this trader ($%)', v_trader.max_copy_amount;
  end if;

  v_roi           := coalesce(v_trader.roi, 0);
  v_duration_days := greatest(1, coalesce(v_trader.profit_days, 30));
  v_expected_profit := round(p_amount_invested * v_roi / 100.0, 2);
  v_total_return  := round(p_amount_invested + v_expected_profit, 2);
  v_end           := v_start + (v_duration_days || ' days')::interval;

  perform set_config('app.bypass_balance_protection', 'true', true);
  update users set balance = balance - p_amount_invested where id = p_user_id and balance >= p_amount_invested;
  if not found then
    raise exception 'Insufficient balance';
  end if;

  insert into copy_trades (
    id, user_id, trader_id, trader_name, amount_invested, roi_percent,
    expected_profit, total_return, start_timestamp, end_timestamp,
    remaining_days, status, payout_completed, progress
  ) values (
    p_id, p_user_id, p_trader_id, v_trader.name, p_amount_invested, v_roi,
    v_expected_profit, v_total_return, v_start, v_end,
    v_duration_days, 'Running', false, 0
  );

  insert into transactions (id, user_id, type, amount, currency, status, related_reference_id, notes)
  values ('tx-copy-' || p_id, p_user_id, 'investment', p_amount_invested, 'USD', 'completed', p_id, 'Copy trade: ' || v_trader.name);
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_copy_trade_payout(p_copy_trade_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_ct record;
  v_caller text := auth.jwt()->>'sub';
begin
  select * into v_ct from copy_trades where id = p_copy_trade_id for update;
  if not found then
    raise exception 'Copy trade not found';
  end if;
  if v_ct.user_id <> v_caller then
    raise exception 'You can only claim your own copy trade payout';
  end if;

  -- Idempotent: already claimed → no-op (prevents double credit).
  if v_ct.status = 'Completed' or v_ct.payout_completed or v_ct.payout_transaction_id is not null then
    return;
  end if;

  if v_ct.status = 'Cancelled' then
    raise exception 'A cancelled copy trade cannot be claimed';
  end if;

  -- Maturity guard.
  if now() < v_ct.end_timestamp then
    raise exception 'Copy trade has not matured yet';
  end if;

  perform set_config('app.bypass_balance_protection', 'true', true);
  update users set balance = balance + v_ct.total_return where id = v_caller;

  update copy_trades
  set status = 'Completed',
      payout_completed = true,
      progress = 100,
      remaining_days = 0,
      completed_at = now(),
      payout_transaction_id = p_copy_trade_id || '-payout'
  where id = p_copy_trade_id;

  insert into transactions (id, user_id, type, amount, currency, status, related_reference_id, notes)
  values (p_copy_trade_id || '-payout', v_caller, 'payout', v_ct.total_return, 'USD', 'completed', p_copy_trade_id, 'Copy trade payout: ' || v_ct.trader_name);
end;
$function$

CREATE OR REPLACE FUNCTION public.reject_deposit_transaction(p_transaction_id text, p_notes text DEFAULT ''::text)
 RETURNS void
